    s.public_key = pub
except AttributeError:
    pass
else:
    raise AssertionError("public_key must be read-only")

# constructor type check
for bad in (pub, "x", None, 42):
    try:
        OneTimeSigner(bad)
    except TypeError:
        pass
    else:
        raise AssertionError("expected TypeError")

# bad message type: TypeError, key not consumed
try:
    s.sign(123)
except TypeError:
    pass
else:
    raise AssertionError("expected TypeError")
assert s.used is False

# first sign matches stateless sign exactly
expected = sign("hello", priv)
sig = s.sign("hello")
assert sig == expected and s.used is True
assert verify("hello", sig, pub)

# subsequent signs raise KeyExhaustedError (a RuntimeError), even same message
assert issubclass(KeyExhaustedError, RuntimeError)
for msg in ("hello", b"other", bytearray(b"x")):
    try:
        s.sign(msg)
    except KeyExhaustedError:
        pass
    else:
        raise AssertionError("expected KeyExhaustedError")

# bytes/bytearray/str accepted on a fresh signer
for msg in (b"m", bytearray(b"m"), "m"):
    priv2, _ = keygen(bits=8)
    s2 = OneTimeSigner(priv2)
    assert s2.sign(msg) == sign(msg, priv2)

# concurrency: at most one success among many racing threads
priv3, _ = keygen(bits=16)
s3 = OneTimeSigner(priv3)
results, errors = [], []
barrier = threading.Barrier(64)
def worker():
    barrier.wait()
    try:
        results.append(s3.sign(b"race"))
    except KeyExhaustedError:
        errors.append(1)
threads = [threading.Thread(target=worker) for _ in range(64)]
for t in threads: t.start()
for t in threads: t.join()
assert len(results) == 1 and len(errors) == 63, (len(results), len(errors))

# stateless sign still reusable
sign("a", priv3); sign("a", priv3)

print("all OneTimeSigner checks passed")
